source saved := "none";
source shown = saved;
action keep(n: number) {
  optimistic shown := "saving";
  try {
    let r = await save(n);
    saved := r;
  } catch (error) {
    saved := "error";
  }
}
<p><button onClick={() => { keep(count) }}>keep</button>{"saved " + shown}<button onClick={() => { store(count) }}>store</button></p>
